const r = await tools.exec_command({cmd:"python -c "import json; from pathlib import Path; from muclegal.ui import CaseArchive; targets=[Path('output/post-acceptance/example')]+[Path(f'output/post-acceptance/real-matrix/target-{i}') for i in range(1,6)]; rows=[];
for root in targets:
 case=json.loads((root/'latest-case.json').read_text(encoding='utf-8')); bundle=Path(case['artifacts']['manifest']).parent; archive=CaseArchive(root); case_id=bundle.name; zip_path=archive.build_download(case_id); roles={};
 for role,g in case.get('capture_galleries',{}).items():
  rr=bundle/'artifacts'/'roles'/g['source_role']; norm=rr/'normalized-text.txt'; clauses=rr/'clauses.json'; idx=rr/'screenshot-index.json'; inter=rr/'interactions.json'; index=json.loads(idx.read_text(encoding='utf-8')) if idx.is_file() else {}; interactions=json.loads(inter.read_text(encoding='utf-8')).get('interactions',[]) if inter.is_file() else []; roles[role]={'text_chars':len(norm.read_text(encoding='utf-8')) if norm.is_file() else None,'clauses':len(json.loads(clauses.read_text(encoding='utf-8')).get('clauses',[])) if clauses.is_file() else None,'screenshot_mode':index.get('mode'),'document_height':index.get('document_height_css_px'),'coverage':index.get('continuous_coverage') if index.get('mode')=='tiles' else index.get('full_page_attempt',{}).get('valid'),'consent':interactions[0].get('result') if interactions else None,'expansions':sum(1 for x in interactions if x.get('type')=='legal_expansion')};
 rows.append({'url':case.get('requested_url') or case['url'],'captured_url':case.get('captured_url'),'capture_completeness':case.get('capture_completeness'),'protection_type':case.get('protection_type'),'warnings':case.get('warnings'),'roles':roles,'bundle_size_bytes':sum(p.stat().st_size for p in bundle.rglob('*') if p.is_file() and p!=zip_path),'zip_size_bytes':zip_path.stat().st_size,'warc_size_bytes':Path(case['artifacts']['warc']).stat().st_size if case['artifacts'].get('warc') else None,'manifest_entries':len(json.loads(Path(case['artifacts']['manifest']).read_text(encoding='utf-8')).get('artifacts',[]))});
